 "content": "from collections import Counter


def transform(grid):
    """Complete the perimeter of the rectangle spanned by sparse markers."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]

    top = min(r for r, _ in points)
    bottom = max(r for r, _ in points)
    left = min(c for _, c in points)
    right = max(c for _, c in points)
    out = [row[:] for row in grid]
    for c in range(left, right + 1):
        if out[top][c] == background:
            out[top][c] = 2
        if out[bottom][c] == background:
            out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if out[r][left] == background:
            out[r][left] = 2
        if out[r][right] == background:
            out[r][right] = 2
    return out


if __name__ == "__main__":
    print("transform(grid) is ready")
